// Live fitting in the browser: the same Rust core as the CLI, compiled to wasm.
// Data slices are generated by scripts/make_docs_figures.py --bundle-slice.
const $ = (id) => document.getElementById(id);
const status = (m) => ($("status").textContent = m);

const CMAPS = {
  gray: (t) => [t * 255, t * 255, t * 255],
  magma: (t) => [255 * Math.min(1, 1.6 * t), 255 * t ** 1.7, 255 * (0.35 * t + 0.55 * t ** 3)],
};

let wasm = null, bundles = {}, current = null, lastMaps = null;

async function loadWasm() {
  try {
    const mod = await import("./pkg/qmrust_wasm.js");
    await mod.default();
    return mod;
  } catch (e) {
    $("fallback").hidden = false;
    status("wasm unavailable");
    return null;
  }
}

async function fetchOrThrow(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: ${r.status}`);
  return r;
}

async function loadBundle(name) {
  if (bundles[name]) return bundles[name];
  const meta = await (await fetchOrThrow(`./data/${name}.json`)).json();
  const buf = await (await fetchOrThrow(`./data/${meta.data}`)).arrayBuffer();
  const all = new Float32Array(buf);
  const [h, w, nz, nt] = meta.dims;
  const spatial = h * w * nz;
  meta.data4 = Float64Array.from(all.subarray(0, spatial * nt));
  meta.maskU8 = meta.mask
    ? Uint8Array.from(all.subarray(spatial * nt, spatial * nt + spatial), (v) => (v > 0 ? 1 : 0))
    : null;
  bundles[name] = meta;
  return meta;
}

function draw(canvas, values, h, w, cmap, mask) {
  canvas.width = w; canvas.height = h;
  const ctx = canvas.getContext("2d");
  const img = ctx.createImageData(w, h);
  const finite = [];
  for (let i = 0; i < values.length; i++) {
    if (Number.isFinite(values[i]) && (!mask || mask[i])) finite.push(values[i]);
  }
  finite.sort((a, b) => a - b);
  const lo = finite[Math.floor(finite.length * 0.02)] ?? 0;
  const hi = finite[Math.floor(finite.length * 0.98)] ?? 1;
  const span = hi > lo ? hi - lo : 1;
  for (let i = 0; i < h * w; i++) {
    const v = values[i];
    const ok = Number.isFinite(v) && (!mask || mask[i]);
    const [r, g, b] = ok ? cmap(Math.max(0, Math.min(1, (v - lo) / span))) : [13, 17, 23];
    img.data.set([r, g, b, 255], i * 4);
  }
  ctx.putImageData(img, 0, 0);
}

function panel(caption, canvas, kind) {
  const fig = document.createElement("figure");
  if (kind) fig.dataset.panel = kind;
  const cap = document.createElement("figcaption");
  cap.textContent = caption;
  fig.append(canvas, cap);
  return fig;
}

function showInputs(meta) {
  const [h, w, , nt] = meta.dims;
  const panels = $("panels");
  panels.replaceChildren();
  const c = document.createElement("canvas");
  // `data4` is t-fastest (voxel i's time course occupies [i*nt, (i+1)*nt)),
  // matching the layout `fit_volume` expects — so volume 0 is every voxel's
  // first sample, not the first h*w floats.
  const n = h * w;
  const first = new Float64Array(n);
  for (let i = 0; i < n; i++) first[i] = meta.data4[i * nt];
  draw(c, first, h, w, CMAPS.gray, meta.maskU8);
  c.onclick = (e) => plotVoxel(meta, e, c);
  panels.append(panel(`${meta.labels[0]} — click a voxel`, c));
  status(`${meta.title}: ${nt} volumes, ${h}×${w}`);
}

function fitSlice(meta) {
  if (!meta) { status("no bundle loaded — pick a model first"); return; }
  status("fitting…");
  const t0 = performance.now();
  // `dims` is `&[usize]` on the Rust side, so it must arrive as a Uint32Array,
  // not a plain JS array.
  // fit_volume returns a JS Map (serde-wasm-bindgen's default encoding for a
  // Rust BTreeMap), not a plain object — flatten it so `maps[name]` works.
  const maps = Object.fromEntries(wasm.fit_volume(
    meta.config, meta.data4, Uint32Array.from(meta.dims),
    JSON.stringify(meta.volume_ids), meta.maskU8 ?? undefined, "{}",
  ));
  lastMaps = maps;
  const [h, w] = meta.dims;
  const panels = $("panels");
  panels.querySelectorAll("[data-panel=output]").forEach((el) => el.remove());
  for (const o of meta.outputs) {
    const values = maps[o.name];
    if (!values) continue;
    const c = document.createElement("canvas");
    draw(c, values, h, w, CMAPS.magma, meta.maskU8);
    panels.append(panel(`${o.name}${o.unit ? ` [${o.unit}]` : ""}`, c, "output"));
  }
  status(`fitted in ${Math.round(performance.now() - t0)} ms`);
}

function plotVoxel(meta, event, canvas) {
  if (!lastMaps) { status("fit the slice first, then click a voxel"); return; }
  const [h, w, , nt] = meta.dims;
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor(((event.clientX - rect.left) / rect.width) * w);
  const y = Math.floor(((event.clientY - rect.top) / rect.height) * h);
  const i = y * w + x;
  const measured = [];
  for (let t = 0; t < nt; t++) measured.push(meta.data4[i * nt + t]);
  const outputNames = new Set(meta.outputs.map((o) => o.name));
  if (!meta.params.every((p) => outputNames.has(p))) {
    status(
      "this model's nuisance parameters are not written as output maps, " +
      "so no curve is available",
    );
    return;
  }
  const params = meta.params.map((p) => lastMaps[p]?.[i] ?? NaN);
  if (params.some((v) => !Number.isFinite(v))) { status("no fit at that voxel"); return; }
  const predicted = JSON.parse(wasm.forward(meta.config, Float64Array.from(params), "{}"));
  const values = Array.isArray(predicted)
    ? predicted.map((s) => s.value)
    : meta.volume_ids.map((r) => predicted[r]);
  drawCurve(measured, values, meta.labels);
  status(
    `voxel (${y}, ${x}) — ` +
      meta.params.map((p, k) => `${p}=${params[k].toPrecision(3)}`).join(", "),
  );
}

function drawCurve(measured, predicted, labels) {
  const id = "curve";
  let c = document.getElementById(id);
  if (!c) {
    c = document.createElement("canvas");
    c.id = id;
    $("panels").append(panel("measured (dots) vs forward model (line)", c));
  }
  const W = 380, H = 190, pad = 26;
  c.width = W; c.height = H;
  const ctx = c.getContext("2d");
  ctx.fillStyle = "#0d1117"; ctx.fillRect(0, 0, W, H);
  const all = measured.concat(predicted).filter(Number.isFinite);
  const lo = Math.min(...all), hi = Math.max(...all);
  const sx = (k) => pad + (k / Math.max(1, measured.length - 1)) * (W - 2 * pad);
  const sy = (v) => H - pad - ((v - lo) / (hi - lo || 1)) * (H - 2 * pad);
  ctx.strokeStyle = "#30363d";
  ctx.beginPath(); ctx.moveTo(pad, pad); ctx.lineTo(pad, H - pad);
  ctx.lineTo(W - pad, H - pad); ctx.stroke();
  ctx.strokeStyle = "#f0883e"; ctx.lineWidth = 1.6; ctx.beginPath();
  predicted.forEach((v, k) => (k ? ctx.lineTo(sx(k), sy(v)) : ctx.moveTo(sx(k), sy(v))));
  ctx.stroke();
  ctx.fillStyle = "#58a6ff";
  measured.forEach((v, k) => {
    ctx.beginPath(); ctx.arc(sx(k), sy(v), 2.6, 0, 2 * Math.PI); ctx.fill();
  });
  void labels;
}

async function main() {
  wasm = await loadWasm();
  let index;
  try {
    index = await (await fetchOrThrow("./data/index.json")).json();
  } catch (e) {
    status(`could not load ./data/index.json (${e.message})`);
    return;
  }
  const select = $("model");
  for (const name of index.models) {
    let meta;
    try {
      meta = await loadBundle(name);
    } catch (e) {
      status(`could not load bundle "${name}" (${e.message})`);
      continue;
    }
    const opt = document.createElement("option");
    opt.value = name; opt.textContent = meta.title;
    select.append(opt);
  }
  $("fit").disabled = !wasm;
  const select_model = async () => {
    try {
      current = await loadBundle(select.value);
    } catch (e) {
      current = null;
      $("fit").disabled = true;
      status(`could not load bundle "${select.value}" (${e.message})`);
      return;
    }
    $("fit").disabled = !wasm;
    lastMaps = null;
    showInputs(current);
  };
  select.onchange = select_model;
  $("fit").onclick = () => fitSlice(current);
  await select_model();
  if (wasm) status("ready — press Fit slice");
}

main();
